-- 0348: seed the client account tree with separate internal four-digit numbers.
--
-- parent_code is the hierarchy; account_code is a stable internal identifier.
-- The 43 previous four-digit accounts and the employee-claim code retain their
-- identities for history, but stop accepting new entries. Source posting remains
-- paused by 0346 until Finance completes the account-map review.

ALTER TABLE ledger_account DROP CONSTRAINT IF EXISTS ledger_account_counterparty_is_rare;
ALTER TABLE ledger_account ADD CONSTRAINT ledger_account_counterparty_is_rare
    CHECK (requires_counter_site = FALSE OR account_code IN (
        '1302', '1501', '1031', '1032', '1057', '1058', '1059', '2028', '2029',
        '1011203001', '1011204001', '1021401001', '1021402001', '1021403001',
        '2012301001', '2012302001'
    ));

-- Keep legacy headings for historical navigation, but show only the new tree
-- in the active chart. Root classes stay active; the replacement groups below
-- are inserted active and preserve all old parent links for retired accounts.
UPDATE ledger_account
   SET is_active = FALSE
 WHERE is_group
   AND account_code NOT IN ('1', '2', '3', '4', '5', '6', '7', '8')
   AND is_active;

