-- Preserve account identifiers used by posted history; retire them for new manual entries.
UPDATE ledger_account SET is_active = FALSE
 WHERE account_code IN ('1101', '1102', '1201', '1202', '1209', '1301', '1302', '1309', '1401', '1402', '1403', '1501', '1601', '1602', '1609', '1610', '1619', '2101', '2102', '2103', '2201', '2301', '2401', '2402', '2501', '2502', '3101', '3102', '3201', '4101', '4201', '4202', '4301', '5101', '5102', '6010210014', '6101', '6201', '6301', '6401', '7101', '8101', '8201', '8301')
   AND is_group = FALSE;

CREATE TABLE ledger_account_source_code (
    source_system text NOT NULL DEFAULT 'CFS_MASTER_ACCOUNT',
    client_account_code text NOT NULL CHECK (client_account_code ~ '^[0-9]+$'),
    client_account_name text NOT NULL CHECK (btrim(client_account_name) <> ''),
    account_code text REFERENCES ledger_account (account_code),
    site_id text REFERENCES site (id),
    counter_site_id text REFERENCES site (id),
    client_is_active boolean NOT NULL,
    mapping_status text NOT NULL CHECK (mapping_status IN ('MAPPED', 'DERIVED_CURRENT_RESULT')),
    mapping_note text,
    PRIMARY KEY (source_system, client_account_code),
    CHECK ((mapping_status = 'MAPPED') = (account_code IS NOT NULL)),
    CHECK (counter_site_id IS NULL OR site_id IS NOT NULL)
);
CREATE INDEX ix_ledger_account_source_code_internal
    ON ledger_account_source_code (account_code, site_id) WHERE account_code IS NOT NULL;
COMMENT ON TABLE ledger_account_source_code IS
    'Client posting codes crosswalk to the internal chart, with site and inter-unit route retained as columns; current-period profit is recorded as derived, not posted.';

-- Crosswalk rows for the 6,908 posting codes in the client master. Fourteen
-- current-period profit rows intentionally have no internal posting account.















DO $$
DECLARE
    active_leaves bigint;
    active_groups bigint;
    mapped_codes bigint;
    derived_codes bigint;
BEGIN
    SELECT count(*) INTO active_leaves FROM ledger_account WHERE is_active AND NOT is_group;
    IF active_leaves <> 267 THEN RAISE EXCEPTION 'expected 267 active chart leaves, got %', active_leaves; END IF;
    SELECT count(*) INTO active_groups FROM ledger_account WHERE is_active AND is_group;
    IF active_groups <> 53 THEN RAISE EXCEPTION 'expected 53 active tree groups including eight roots, got %', active_groups; END IF;
    IF EXISTS (SELECT 1 FROM ledger_account WHERE is_active AND NOT is_group AND length(account_code) <> 4) THEN
        RAISE EXCEPTION 'an active posting account does not use a four-digit internal code';
    END IF;
    IF EXISTS (SELECT 1 FROM ledger_account WHERE is_active AND NOT is_group AND NOT posting_policy_configured) THEN
        RAISE EXCEPTION 'an active chart leaf has no manual posting policy';
    END IF;
    SELECT count(*) INTO mapped_codes FROM ledger_account_source_code WHERE mapping_status = 'MAPPED';
    SELECT count(*) INTO derived_codes FROM ledger_account_source_code WHERE mapping_status = 'DERIVED_CURRENT_RESULT';
    IF mapped_codes <> 6894 OR derived_codes <> 14 THEN
        RAISE EXCEPTION 'expected 6,894 mapped client codes and 14 derived results, got % and %', mapped_codes, derived_codes;
    END IF;
END $$;
